// ArticleFacade.kt L25-33 → createArticle
func (s *articleFacadeImpl) CreateArticle(ctx context.Context, request CreateArticleRequest, author User) (ArticleView, error) {
    id := uuid.New().String()
    newArticle := request.ToArticle(id, author.ID)
    savedArticle, err := s.repo.SaveArticle(ctx, newArticle)
    if err != nil {
        return ArticleView{}, fmt.Errorf("save article: %w", err)
    }
    if err := s.repo.SaveAllTags(ctx, savedArticle.Tags); err != nil {
        return ArticleView{}, fmt.Errorf("save tags: %w", err)
    }
    authorProfileView := author.ToOwnProfileView()
    return savedArticle.ToArticleView(authorProfileView, author), nil
}

