func (h *Handler) FindArticles(w http.ResponseWriter, r *http.Request) {
    query := r.URL.Query()
    tag := query.Get("tag")
    authorName := query.Get("authorName")
    favoritedByUser := query.Get("favoritedByUser")
    offset, err := strconv.ParseInt(query.Get("offset"), 10, 64)
    if err != nil {
        httpx.WriteError(w, http.StatusBadRequest, "INVALID_OFFSET", "offset must be a number")
        return
    }
    limit, err := strconv.Atoi(query.Get("limit"))
    if err != nil {
        httpx.WriteError(w, http.StatusBadRequest, "INVALID_LIMIT", "limit must be a number")
        return
    }
    userID, _ := auth.UserIDFromContext(r.Context())
    articles, err := h.svc.FindArticles(r.Context(), tag, authorName, favoritedByUser, offset, limit, userID)
    if err != nil {
        httpx.WriteInternal(w, r, err)
        return
    }
    httpx.WriteJSON(w, http.StatusOK, articles)
}

// ArticleFacade.kt L79-85 → feed
func (s *articleFacadeImpl) Feed(ctx context.Context, offset int64, limit int, user User) (MultipleArticlesView, error) {
    articles, err := s.repo.FindNewestArticlesByAuthorIds(ctx, user.FollowingIds, offset, limit)
    if err != nil {
        return MultipleArticlesView{}, fmt.Errorf("feed: %w", err)
    }
    var articleViews []ArticleView
    for _, article := range articles {
        articleView := mapToArticleView(article, user)
        articleViews = append(articleViews, articleView)
    }
    return toMultipleArticlesView(articleViews), nil
}

// ArticleFacade.kt L97-103 → favoriteArticle
func (s *articleFacadeImpl) FavoriteArticle(ctx context.Context, slug string, currentUser User) (ArticleView, error) {
    article, err := s.articleRepo.FindBySlug(ctx, slug)
    if err != nil {
        return ArticleView{}, fmt.Errorf("find article by slug: %w", err)
    }
    currentUser.Favorite(article)
    if err := s.userRepo.Save(ctx, currentUser); err != nil {
        return ArticleView{}, fmt.Errorf("save user: %w", err)
    }
    return mapToArticleView(article, currentUser), nil
}

// ArticleFacade.kt L104-110 → unfavoriteArticle
func (s *articleFacadeImpl) UnfavoriteArticle(ctx context.Context, slug string, currentUser User) (ArticleView, error) {
    article, err := s.articleRepo.FindBySlug(ctx, slug)
    if err != nil {
        return ArticleView{}, fmt.Errorf("find article by slug: %w", err)
    }

    if err := currentUser.Unfavorite(article); err != nil {
        return ArticleView{}, fmt.Errorf("unfavorite article: %w", err)
    }

    if err := s.userRepo.Save(ctx, currentUser); err != nil {
        return ArticleView{}, fmt.Errorf("save user: %w", err)
    }

    return s.mapToArticleView(article, currentUser), nil
}

